export function boundedWeightedSum(values: readonly bigint[], cap: bigint): bigint {
  let sum = 0n;

  for (let i = 0; i < values.length; i++) {
    const value = values[i];
    const clamped = value < -cap ? -cap : value > cap ? cap : value;
    sum += clamped * BigInt(i + 1);
  }

  return sum;
}

