pub enum TransitionError {
    EventNotAllowed,
    TerminalState,
}

#[derive(Debug, PartialEq, Eq)]
pub enum TransitionResult {
    Accepted(OrderState),
    Rejected(TransitionError),
}

pub fn transition(state: OrderState, event: OrderEvent) -> TransitionResult {
    match state {
        OrderState::Draft => match event {
            OrderEvent::Submit => TransitionResult::Accepted(OrderState::Submitted),
            OrderEvent::Pay => {
                TransitionResult::Rejected(TransitionError::EventNotAllowed)
