export function signedGcd(a: bigint, b: bigint): bigint {
  if (a < 0n) {
    a = -a;
  }
  if (b < 0n) {
    b = -b;
  }

  while (b !== 0n) {
    const remainder = a % b;
    a = b;
    b = remainder;
  }

  return a;
}

